<div class="container-fluid py-4">
    <div class="d-flex align-items-center justify-content-between flex-wrap gap-3 mb-4"><div><p class="text-muted mb-1">CNAM</p><h1 class="h3 mb-0">Demandes de remboursement</h1></div><span class="badge bg-light text-dark"><?= count($liste) ?> demande(s)</span></div>
    <?php if (isset($_SESSION['flash'])): ?><div class="alert alert-<?= e($_SESSION['flash']['type']) ?>" role="status"><?= e($_SESSION['flash']['message']) ?></div><?php unset($_SESSION['flash']); endif; ?>
    <form class="d-flex flex-wrap align-items-end gap-2 mb-4" method="get" action="index.php"><input type="hidden" name="page" value="admin-demandes-cnam"><div><label class="form-label" for="filtre-statut">Filtrer par statut</label><select class="form-select" id="filtre-statut" name="statut"><option value="">Tous les statuts</option><?php foreach (DemandeRemboursementController::STATUTS as $s): ?><option value="<?= e($s) ?>" <?= ($_GET['statut']??'')===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary" type="submit">Filtrer</button></form>
