    <?php foreach ($liste as $d): ?><article class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-start flex-wrap gap-3"><div><p class="text-muted mb-1"><bdi><?= e($d['reference']) ?></bdi> · <?= e($d['statut']) ?></p><h2 class="h5 mb-1"><?= e($d['prenom'].' '.$d['nom']) ?> <span class="text-muted fw-normal">· <?= e($d['matricule_cnam']) ?></span></h2><p class="mb-2"><?= e($d['nature_soins']) ?> · <?= e(date('d/m/Y',strtotime($d['date_soins']))) ?> · <bdi><?= e(number_format((float)$d['montant_demande'],3,',',' ')) ?> TND</bdi></p><?php if ($d['date_depot']): ?><small class="text-muted">Déposée le <?= e(date('d/m/Y H:i',strtotime($d['date_depot']))) ?></small><?php endif; ?></div><span class="badge bg-light text-dark">v<?= e($d['version']) ?></span></div>
        <div class="my-3"><strong>Justificatifs</strong><ul class="mb-0"><?php foreach ($documentsParDemande[(int)$d['id_demande']]??[] as $doc): ?><li><a href="index.php?page=document-cnam&amp;id=<?= e($doc['id_document']) ?>"><?= e($doc['nom_original']) ?></a> <small class="text-muted">· <?= e(number_format($doc['taille']/1024,0)) ?> Ko</small></li><?php endforeach; ?><?php if (empty($documentsParDemande[(int)$d['id_demande']])): ?><li>—</li><?php endif; ?></ul></div>
        <?php $histoire=$decisionsParDemande[(int)$d['id_demande']]??[]; if ($histoire): ?><details class="mb-3"><summary>Historique des décisions (<?= count($histoire) ?>)</summary><ul class="mt-2"><?php foreach ($histoire as $h): ?><li><?= e($h['resultat']) ?> · <?= e(trim($h['auteur_prenom'].' '.$h['auteur_nom'])) ?> · <?= e(date('d/m/Y H:i',strtotime($h['date_decision']))) ?> — <?= e($h['motif']) ?><?php if ($h['montant_accorde']!==null): ?> · <?= e(number_format((float)$h['montant_accorde'],3,',',' ')) ?> TND<?php endif; ?></li><?php endforeach; ?></ul></details><?php endif; ?>
        <?php if ($peutTraiter && $d['statut']==='DEPOSEE'): ?><form method="post" action="index.php?page=cnam-prise-en-charge"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id_demande" value="<?= e($d['id_demande']) ?>"><input type="hidden" name="version" value="<?= e($d['version']) ?>"><button class="btn btn-primary" type="submit">Prendre en charge</button></form>
        <?php elseif ($peutTraiter && $d['statut']==='EN_ETUDE'): ?><form class="row g-2 align-items-end" method="post" action="index.php?page=cnam-decision"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id_demande" value="<?= e($d['id_demande']) ?>"><input type="hidden" name="version" value="<?= e($d['version']) ?>"><div class="col-md-3"><label class="form-label" for="resultat-<?= e($d['id_demande']) ?>">Décision</label><select class="form-select" id="resultat-<?= e($d['id_demande']) ?>" name="resultat" required><option value="A_COMPLETER">À compléter</option><option value="ACCEPTEE">Accepter</option><option value="REFUSEE">Refuser</option></select></div><div class="col-md-3"><label class="form-label" for="montant-<?= e($d['id_demande']) ?>">Montant accordé (TND)</label><input class="form-control" id="montant-<?= e($d['id_demande']) ?>" type="number" name="montant_accorde" min="0" max="<?= e($d['montant_demande']) ?>" step="0.001"></div><div class="col-md-4"><label class="form-label" for="motif-<?= e($d['id_demande']) ?>">Motif</label><input class="form-control" id="motif-<?= e($d['id_demande']) ?>" name="motif" maxlength="2000" required></div><div class="col-md-2"><button class="btn btn-primary w-100" type="submit">Enregistrer</button></div></form>
        <?php elseif ($peutTraiter && $d['statut']==='ACCEPTEE'): ?><form class="row g-2 align-items-end" method="post" action="index.php?page=cnam-versement"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id_demande" value="<?= e($d['id_demande']) ?>"><input type="hidden" name="version" value="<?= e($d['version']) ?>"><div class="col-md-4"><label class="form-label" for="date-versement-<?= e($d['id_demande']) ?>">Date du versement manuel</label><input class="form-control" id="date-versement-<?= e($d['id_demande']) ?>" type="date" name="date_versement" max="<?= e(date('Y-m-d')) ?>" required></div><div class="col-md-5"><label class="form-label" for="reference-versement-<?= e($d['id_demande']) ?>">Référence de versement</label><input class="form-control" id="reference-versement-<?= e($d['id_demande']) ?>" name="reference_versement" maxlength="100" required></div><div class="col-md-3"><button class="btn btn-success w-100" type="submit">Confirmer le versement</button></div></form><?php endif; ?>
    </div></article><?php endforeach; ?></div><?php endif; ?>
